// ─────────────────────────────────────────────
// Modbus 헬스 응답
// 워치독 상태 (global watchdogStatus) 기반
// ─────────────────────────────────────────────
var status = global.get('watchdogStatus') || null;
var alert  = global.get('watchdogAlert')  || null;

var healthy = true;
var reasons = [];

if (!status) {
    healthy = false;
    reasons.push('워치독 미초기화 (Node-RED 시작 직후 또는 모듈 없음)');
} else if (alert) {
    // 워치독 임계치 초과한 모듈 1개라도 있으면 unhealthy
    healthy = false;
    reasons.push('Modbus 모듈 장애: ' + Object.keys(alert).join(', '));
}

var lastCheck = status && status.lastCheck ? new Date(status.lastCheck) : null;
if (lastCheck) {
    var ageSec = (Date.now() - lastCheck.getTime()) / 1000;
    if (ageSec > 180) {
        // 워치독이 3분 넘게 안 돈 경우 — Node-RED hang 가능성
        healthy = false;
        reasons.push('워치독 정지 ' + Math.floor(ageSec) + '초 (hang 의심)');
    }
}

msg.statusCode = healthy ? 200 : 503;
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = {
    healthy: healthy,
    lastCheck: status ? status.lastCheck : null,
    modules: status || {},
    alert: alert,
    reasons: reasons,
    timestamp: new Date().toISOString()
};
return msg;
